export function casualSystemPrompt(userSystem?: string): string {
  const custom = userSystem?.trim() ? `${userSystem.trim()}\n\n` : "";
  return `${custom}You are a helpful assistant. Answer the user's message directly. Do not mention files, folders, commands, or the workspace.`;
}

export function toolCapabilityNote(): string {
  return `Computer tools run only when you make a real tool call. A sentence that names a tool does not run it.
read_file, list_dir, and search_in_files read the workspace.
write_file, patch_file, and delete_file change files.
run_command runs PowerShell on this computer, including setup and install commands.
read_document reads txt, md, pdf, docx, and pptx. The server extracts the text before you see it.
sample_video splits a video with ffmpeg before any model sees it. Set interval_seconds to the gap between frames. A vision model then describes those frames. Call sample_video again when you want a different gap.
launch_app opens an installed program by its name or its full exe path, such as blender. Say that it opened only when the tool result says Started.
computer_action performs one PC check or change. action is bluetooth_status, bluetooth_on, bluetooth_off, firewall_status, firewall_on, firewall_off, process_status, service_status, disk_space, memory_status, wifi_status, network_status, components_status, battery_status, cpu_status, gpu_status, display_status, audio_status, volume_status, volume_set, volume_mute, volume_unmute, printers_status, camera_status, power_status, startup_status, programs_status, devices_status, screenshot, speak, listen, transcribe, sleep, restart, shutdown, process_stop, service_start, service_stop, device_enable, or device_disable. components_status reports the operating system, CPU, memory, battery, GPU, disks, audio, network adapters, Bluetooth devices, printers, cameras, and the power plan. target is the process name, service name, a program search, a volume from 0 to 100, words to speak, or an audio file. Turn the firewall off only when the user asked for that. A process is running only when the result shows a pid. sleep, restart, and shutdown run only when the user asked for that action in this message. process_stop, service_start, service_stop, device_enable, and device_disable are allowed for a named target. Leave System, lsass, svchost, the keyboard, the mouse, and the display alone. speak uses the Windows voice. listen uses the Windows speech recognizer for a few seconds. transcribe uses the local whisper.cpp model. The chat models still cannot hear by themselves. brightness_status, brightness_up, brightness_down, and brightness_set change the screen when the display supports it. theme_status, theme_dark, and theme_light read or set the Windows app theme. defaults_status reads default apps. defaults_open opens Windows Settings. windows_update_status reads recent update history. windows_update_scan looks for pending updates. windows_update_install installs pending updates and can ask Windows to restart. clipboard_read reads the clipboard and hides values that look like passwords. ui_type and ui_click focus a named window. A scanned PDF is passed through Windows OCR when it has no text layer.`;
}

export function conversationSystemPrompt(userSystem?: string): string {
  const custom = userSystem?.trim() ? `${userSystem.trim()}\n\n` : "";
  return `${custom}You are a helpful assistant. Answer from the conversation. Do not invent file contents, package names, licenses, or tool results.`;
}

export function evidenceSystemPrompt(options: {
  userSystem?: string;
  workspace: string;
  evidence: string;
  sessionNote?: string;
}): string {
  const custom = options.userSystem?.trim() ? `${options.userSystem.trim()}\n\n` : "";
  const note = options.sessionNote?.trim() ? `\n\n${options.sessionNote.trim()}` : "";
  return `${custom}You are a coding assistant. The server already read the workspace. Every project fact in your reply must appear in the evidence below or in a later tool result. If a name is not there, do not say it. You may ask to read another file inside the workspace, then answer. List the files that were read. Do not tell the user to run a command. Do not say you lack filesystem access.

Workspace: ${options.workspace}

Evidence:
${options.evidence}${note}`;
}
